<?php
declare(strict_types=1);
namespace CommunityHub;
final class Learning {
 public static function assessment(int $lesson,bool $key=false):array{return ['questions'=>App::rows('SELECT id,question_text,question_type,points FROM lms_quiz_questions WHERE lesson_id=? ORDER BY sort_order,id',[$lesson]),'answers'=>App::rows('SELECT a.id,a.question_id,a.answer_text'.($key?',a.is_correct':'').' FROM lms_quiz_answers a JOIN lms_quiz_questions q ON q.id=a.question_id WHERE q.lesson_id=? ORDER BY a.sort_order,a.id',[$lesson])];}
 public static function grade(array $questions,array $answers,array $selections):float{if(!$questions)throw new HttpError('This assessment has no questions yet.',409);$earned=0;$total=0;foreach($questions as $q){$options=array_values(array_filter($answers,fn($a)=>(string)$a['question_id']===(string)$q['id']));if(count($options)<2||count(array_filter($options,fn($a)=>(int)$a['is_correct']===1))!==1||(float)$q['points']<=0)throw new HttpError('This assessment is not ready. Contact your instructor.',409);$selected=null;foreach($options as $a)if((string)$a['id']===(string)($selections[$q['id']]??''))$selected=$a;if(!$selected)throw new HttpError('Answer every question using one of its listed choices.');$total+=(float)$q['points'];if((int)$selected['is_correct']===1)$earned+=(float)$q['points'];}return round($earned/$total*100,2);}
 public static function enroll(array $u,int $course):void{App::transaction(function()use($u,$course){$c=App::row("SELECT * FROM lms_courses WHERE id=? AND status='published' FOR UPDATE",[$course]);if(!$c||($c['department_id']&&$c['department_id']!=$u['department_id']))throw new HttpError('Course unavailable.',404);$prereqs=App::rows("SELECT p.prerequisite_course_id,e.id completed FROM lms_course_prerequisites p LEFT JOIN lms_enrollments e ON e.course_id=p.prerequisite_course_id AND e.user_id=? AND e.status='completed' WHERE p.course_id=?",[$u['id'],$course]);if(array_filter($prereqs,fn($p)=>!$p['completed']))throw new HttpError('Complete the prerequisite courses first.',409);App::query("INSERT INTO lms_enrollments(course_id,user_id) VALUES(?,?) ON DUPLICATE KEY UPDATE user_id=VALUES(user_id)",[$course,$u['id']]);});}
 public static function complete(int $user,int $course,int $lesson,?array $selections=null):array{return App::transaction(function()use($user,$course,$lesson,$selections){$e=App::row('SELECT e.*,c.title,c.status course_status,c.passing_score,c.certification_id,c.certificate_valid_days FROM lms_enrollments e JOIN lms_courses c ON c.id=e.course_id WHERE e.user_id=? AND e.course_id=? FOR UPDATE',[$user,$course]);if(!$e)throw new HttpError('Enroll in this course first.',403);if($e['course_status']!=='published')throw new HttpError('This course is unavailable.',409);$l=App::row('SELECT l.* FROM lms_lessons l JOIN lms_modules m ON m.id=l.module_id WHERE l.id=? AND m.course_id=?',[$lesson,$course]);if(!$l)throw new HttpError('Lesson not found.',404);if($e['status']==='completed')return ['completed'=>true];$score=null;$passed=true;if($l['lesson_type']==='quiz'){if($selections===null)throw new HttpError('Submit the assessment to complete this lesson.');$assessment=self::assessment($lesson,true);$score=self::grade($assessment['questions'],$assessment['answers'],$selections);$passed=$score>=(float)($e['passing_score']??70);App::query('INSERT INTO lms_assessment_attempts(enrollment_id,lesson_id,score,passed) VALUES(?,?,?,?)',[$e['id'],$lesson,$score,(int)$passed]);}elseif($selections!==null)throw new HttpError('This lesson is not an assessment.');App::query("INSERT INTO lms_lesson_progress(enrollment_id,lesson_id,status,score,started_at,completed_at) VALUES(?,?,?,?,NOW(),IF(?=1,NOW(),NULL)) ON DUPLICATE KEY UPDATE score=IF(status='completed',score,VALUES(score)),completed_at=IF(status='completed',completed_at,VALUES(completed_at)),status=IF(status='completed',status,VALUES(status)),started_at=COALESCE(started_at,NOW())",[$e['id'],$lesson,$passed?'completed':'in_progress',$score,(int)$passed]);$required=App::rows('SELECT l.lesson_type,p.status,p.score FROM lms_lessons l JOIN lms_modules m ON m.id=l.module_id LEFT JOIN lms_lesson_progress p ON p.lesson_id=l.id AND p.enrollment_id=? WHERE m.course_id=? AND l.is_required=1',[$e['id'],$course]);$done=array_filter($required,fn($r)=>$r['status']==='completed'&&($r['lesson_type']!=='quiz'||($r['score']!==null&&(float)$r['score']>=(float)($e['passing_score']??70))));$completed=count($required)>0&&count($done)===count($required);$pct=$required?(int)floor(count($done)/count($required)*100):0;$quizzes=array_filter($done,fn($r)=>$r['lesson_type']==='quiz');$final=$quizzes?array_sum(array_column($quizzes,'score'))/count($quizzes):null;App::query('UPDATE lms_enrollments SET status=?,progress_percent=?,final_score=?,started_at=COALESCE(started_at,NOW()),completed_at=IF(?=1,NOW(),NULL) WHERE id=?',[$completed?'completed':'in_progress',$pct,$completed?$final:null,(int)$completed,$e['id']]);if($completed){if($e['certification_id']){$days=$e['certificate_valid_days']?:null;App::query('INSERT INTO user_certifications(user_id,certification_id,awarded_at,expires_at,notes) VALUES(?,?,NOW(),IF(? IS NULL,NULL,DATE_ADD(NOW(),INTERVAL ? DAY)),?) ON DUPLICATE KEY UPDATE awarded_by=NULL,awarded_at=NOW(),expires_at=VALUES(expires_at),notes=VALUES(notes)',[$user,$e['certification_id'],$days,$days,'Awarded by LMS course: '.$e['title']]);}App::query('INSERT INTO notifications(user_id,title,message,url) VALUES(?,?,?,?)',[$user,'Course completed','You completed '.$e['title'].($e['certification_id']?' and earned its certification':''),'/lms/courses/'.$course]);App::audit($user,'lms.completed','lms_enrollment',(int)$e['id'],['course_id'=>$course,'score'=>$final,'certification_id'=>$e['certification_id']]);Automation::emit('lms_completed',['entity_type'=>'lms_course','entity_id'=>$course,'subject_user_id'=>$user,'course_id'=>$course,'enrollment_id'=>(int)$e['id'],'score'=>$final,'certification_id'=>$e['certification_id']]);}return ['completed'=>$completed,'passed'=>$passed,'score'=>$score];});}
 public static function addQuestion(int $course,int $lesson,array $d):void{$text=App::text($d['question_text']??null,'Question',4000);$type=($d['question_type']??'')==='true_false'?'true_false':'single';$choices=$type==='true_false'?['True','False']:array_values(array_filter(array_map('trim',preg_split('/\R/',(string)($d['choices']??''))),fn($v)=>$v!==''));$correct=filter_var($d['correct_choice']??null,FILTER_VALIDATE_INT);$points=$d['points']??1;if(count($choices)<2||count($choices)>8||$correct===false||$correct<1||$correct>count($choices)||!is_numeric($points)||(float)$points<0.01||(float)$points>1000||array_filter($choices,fn($v)=>mb_strlen($v)>1000))throw new HttpError('Enter a question, 2–8 choices, a valid correct choice number and points between 0.01 and 1000.');App::transaction(function()use($course,$lesson,$text,$type,$choices,$correct,$points){$c=App::row('SELECT status FROM lms_courses WHERE id=? FOR UPDATE',[$course]);if(!$c||$c['status']!=='draft')throw new HttpError('Set the course to draft before editing assessments.');if(!App::row("SELECT l.id FROM lms_lessons l JOIN lms_modules m ON m.id=l.module_id WHERE l.id=? AND m.course_id=? AND l.lesson_type='quiz'",[$lesson,$course]))throw new HttpError('Assessment not found in this course.');$order=App::row('SELECT COALESCE(MAX(sort_order),-1)+1 n FROM lms_quiz_questions WHERE lesson_id=?',[$lesson]);$id=App::insert('INSERT INTO lms_quiz_questions(lesson_id,question_text,question_type,points,sort_order) VALUES(?,?,?,?,?)',[$lesson,$text,$type,$points,$order['n']]);foreach($choices as $i=>$choice)App::query('INSERT INTO lms_quiz_answers(question_id,answer_text,is_correct,sort_order) VALUES(?,?,?,?)',[$id,$choice,(int)($i+1===$correct),$i]);});}
}
